CREATE TABLE IF NOT EXISTS product_reviews (id CHAR(36) PRIMARY KEY,product_id CHAR(36) NOT NULL,reviewer_name VARCHAR(80) NOT NULL,rating TINYINT NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT product_reviews_fk FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,CONSTRAINT product_rating_check CHECK (rating BETWEEN 1 AND 5),INDEX product_reviews_product_idx(product_id,created_at));
CREATE TABLE IF NOT EXISTS shop_reviews (id CHAR(36) PRIMARY KEY,seller_id CHAR(36) NOT NULL,reviewer_name VARCHAR(80) NOT NULL,rating TINYINT NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT shop_reviews_fk FOREIGN KEY(seller_id) REFERENCES sellers(id) ON DELETE CASCADE,CONSTRAINT shop_rating_check CHECK (rating BETWEEN 1 AND 5),INDEX shop_reviews_seller_idx(seller_id,created_at));
